import{_ as e,a as o,b as i,c as r,d as a,e as l,f as n,g as s}from"./chunks/minus.DBfYBGdJ.js";import{_ as d,o as c,c as p,a6 as h}from"./chunks/framework.mtgKxyez.js";const v=JSON.parse('{"title":"1. Controller Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/basic/1.md","filePath":"en/basic/1.md"}'),m={name:"en/basic/1.md"};function u(g,t,b,x,_,y){return c(),p("div",null,[...t[0]||(t[0]=[h('<h1 id="_1-controller-introduction" tabindex="-1">1. Controller Introduction <a class="header-anchor" href="#_1-controller-introduction" aria-label="Permalink to &quot;1. Controller Introduction&quot;">​</a></h1><h2 id="meet-the-controller" tabindex="-1">Meet the Controller <a class="header-anchor" href="#meet-the-controller" aria-label="Permalink to &quot;Meet the Controller&quot;">​</a></h2><p>There are two controller styles, as shown below: the older oval controller and the newer T-shaped controller. The robot arms at YMSH use the older controller, so this chapter focuses on that one.</p><div style="display:flex;justify-content:center;align-items:flex-end;gap:20px;text-align:center;margin:20px 0;"><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+e+'" alt="Old controller" style="height:200px;width:auto;border-radius:8px;"><span style="color:#888;font-size:0.85em;margin-top:8px;">Old controller</span></div><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+o+'" alt="New controller" style="height:200px;width:auto;border-radius:8px;"><span style="color:#888;font-size:0.85em;margin-top:8px;">New controller</span></div></div><h2 id="the-buttons" tabindex="-1">The Buttons <a class="header-anchor" href="#the-buttons" aria-label="Permalink to &quot;The Buttons&quot;">​</a></h2><h3 id="the-big-red-button" tabindex="-1">The Big Red Button <a class="header-anchor" href="#the-big-red-button" aria-label="Permalink to &quot;The Big Red Button&quot;">​</a></h3><p>On the older controller, to the right of the six smaller buttons, there is a very big, very red button. That is the emergency stop.</p><p>Normally you do not need to touch it. Once it is pressed, the robot arm cuts power and stops immediately. In 99.99% of cases, you will not use it. But if you accidentally press it, for example by dropping the controller and slamming the button down, turn the red button clockwise all the way, then pull it upward to release the emergency stop.</p><h3 id="the-six-small-buttons" tabindex="-1">The Six Small Buttons <a class="header-anchor" href="#the-six-small-buttons" aria-label="Permalink to &quot;The Six Small Buttons&quot;">​</a></h3><p>To the right of the emergency stop are six function buttons. From top to bottom and left to right, they are:</p><ul><li><img src="'+i+'" alt="POWER button icon" style="width:30px;display:inline;vertical-align:middle;margin:0 5px;"> <code>POWER</code>: used to power on the robot arm</li><li><img src="'+r+'" alt="STOP button icon" style="width:30px;display:inline;vertical-align:middle;margin:0 5px;"> <code>STOP</code>: stops a running project or motion, or exits certain pages</li><li><img src="'+a+'" alt="M/A button icon" style="width:30px;display:inline;vertical-align:middle;margin:0 5px;"> <code>M/A</code>: switches between manual and automatic mode; after startup, switch to manual mode before operating</li><li><img src="'+l+'" alt="PLAY/PAUSE button icon" style="width:30px;display:inline;vertical-align:middle;margin:0 5px;"> <code>PLAY/PAUSE</code>: starts or pauses a project, and in some operations you must hold it as instructed</li><li><img src="'+n+'" alt="+ button icon" style="width:30px;display:inline;vertical-align:middle;margin:0 5px;"> <code>+</code>: fine-tunes coordinate values, adjusts project speed, or is held during some prompted operations</li><li><img src="'+s+'" alt="- button icon" style="width:30px;display:inline;vertical-align:middle;margin:0 5px;"> <code>-</code>: fine-tunes coordinate values or adjusts project speed</li></ul>',11)])])}const T=d(m,[["render",u]]);export{v as __pageData,T as default};
